import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class Patch implements Opcodes{
 static int hooks;static final String H="dev/zomboid/firstaid/ArmorTolerance";static MethodInsnNode call(String n,String d){return new MethodInsnNode(INVOKESTATIC,H,n,d,false);}static void check(int n,int want,String text){if(n!=want)throw new IllegalStateException(text+" "+n);hooks++;System.out.println(text);}
 static byte[]patch(byte[]b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int before=hooks;for(MethodNode m:c.methods){
 if(c.name.equals("ichttt/mods/firstaid/common/damagesystem/DamageablePart")&&m.name.equals("damage")&&m.desc.equals("(FLnet/minecraft/world/entity/player/Player;ZF)F")){int replaced=0,returns=0,amount=-1;for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof MethodInsnNode mc&&mc.owner.equals("ichttt/mods/firstaid/survival/CriticalCare")&&mc.name.equals("damage")){if(a.getNext()instanceof VarInsnNode v&&v.getOpcode()==FSTORE)amount=v.var;m.instructions.insertBefore(a,new VarInsnNode(ALOAD,2));mc.owner=H;mc.desc="(Ljava/lang/Object;FLjava/lang/Object;)F";replaced++;}check(replaced,1,"local armor from the actual hit body part");if(amount<0)throw new IllegalStateException("missing applied amount local");for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==FRETURN){InsnList x=new InsnList();x.add(new VarInsnNode(FLOAD,1));x.add(new VarInsnNode(FLOAD,amount));x.add(call("leftover","(FFF)F"));m.instructions.insertBefore(a,x);returns++;}check(returns,2,"restore raw units for overflow into other parts");}
 if(c.name.equals("ichttt/mods/firstaid/common/util/ArmorUtils")&&m.name.equals("applyArmor")){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==FRETURN){InsnList x=new InsnList();x.add(new VarInsnNode(FLOAD,3));x.add(call("restoreArmorDamage","(FF)F"));m.instructions.insertBefore(a,x);n++;}check(n,2,"keep armor durability but avoid double ballistic reduction");}
 if(c.name.equals("ichttt/mods/firstaid/survival/ClinicalHooks")&&m.name.equals("distribute")){
  LabelNode start=new LabelNode(),end=new LabelNode(),handler=new LabelNode();InsnList entry=new InsnList();entry.add(new VarInsnNode(ALOAD,4));entry.add(call("enter","(Ljava/lang/Object;)V"));entry.add(start);m.instructions.insert(entry);int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==FRETURN){m.instructions.insertBefore(a,call("exit","()V"));n++;}check(n,1,"nested bullet source context restored on normal return");int error=m.maxLocals;m.maxLocals++;
  m.instructions.add(end);m.instructions.add(handler);m.instructions.add(new FrameNode(F_FULL,7,new Object[]{"ichttt/mods/firstaid/api/distribution/IDamageDistributionAlgorithm","ichttt/mods/firstaid/api/damagesystem/AbstractPlayerDamageModel",FLOAT,"net/minecraft/world/entity/player/Player","net/minecraft/world/damagesource/DamageSource",INTEGER,INTEGER},1,new Object[]{"java/lang/Throwable"}));m.instructions.add(new VarInsnNode(ASTORE,error));m.instructions.add(call("exit","()V"));m.instructions.add(new VarInsnNode(ALOAD,error));m.instructions.add(new InsnNode(ATHROW));m.tryCatchBlocks.add(new TryCatchBlockNode(start,end,handler,null));hooks++;System.out.println("source context restored on exceptions");
 }
 }
 if(before==hooks)return b;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);for(MethodNode m:v.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(v.name,m);return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]>r=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[]b=z.getInputStream(e).readAllBytes();r.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}try(var files=Files.walk(Path.of(a[2]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList())r.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}if(hooks!=5)throw new IllegalStateException("hook total "+hooks);try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:r.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}}
}
